  CREATE TABLE COUNTRIES
   (	COUNTRY_ID CHAR(2) COMMENT 'Primary key of countries table.', 
	COUNTRY_NAME VARCHAR(40) COMMENT 'Country name', 
	REGION_ID INT COMMENT 'Region ID for the country. Foreign key to region_id column in the departments table.', 
	PRIMARY KEY (COUNTRY_ID)
   );
  ALTER TABLE COUNTRIES COMMENT = 'country table. Contains 25 rows. References with locations table.';

  CREATE TABLE DEPARTMENTS 
   (	DEPARTMENT_ID INT COMMENT 'Primary key column of departments table.', 
	DEPARTMENT_NAME VARCHAR(30) COMMENT 'A not null column that shows name of a department. Administration, Marketing, Purchasing, Human Resources, Shipping, IT, Executive, Public Relations, Sales, Finance, and Accounting.', 
	LOCATION_ID INT COMMENT 'Location id where a department is located. Foreign key to location_id column of locations table.', 
	PRIMARY KEY (DEPARTMENT_ID)
   );
  ALTER TABLE DEPARTMENTS COMMENT = 'Departments table that shows details of departments where employees work. Contains 27 rows; references with locations, employees, and job_history tables.';


  CREATE TABLE EMPLOYEES 
   (	EMPLOYEE_ID INT COMMENT 'Primary key of employees table.', 
	FIRST_NAME VARCHAR(20) COMMENT 'First name of the employee. A not null column.', 
	LAST_NAME VARCHAR(25) COMMENT 'Last name of the employee. A not null column.', 
	EMAIL VARCHAR(25) COMMENT 'Email id of the employee', 
	PHONE_NUMBER VARCHAR(20) COMMENT 'Phone number of the employee; includes country code and area code', 
	HIRE_DATE DATE COMMENT 'Date when the employee started on this job. A not null column.', 
	JOB_ID VARCHAR(10) COMMENT 'Current job of the employee; foreign key to job_id column of the jobs table. A not null column.', 
	SALARY INT COMMENT 'Monthly salary of the employee. Must be greater than zero (enforced by constraint emp_salary_min)', 
	COMMISSION_PCT INT COMMENT 'Commission percentage of the employee; Only employees in sales department elgible for commission percentage', 
	MANAGER_ID INT COMMENT 'Manager id of the employee; has same domain as manager_id in departments table. Foreign key to employee_id column of employees table. (useful for reflexive joins and CONNECT BY query)', 
	DEPARTMENT_ID INT COMMENT 'Department id where employee works; foreign key to department_id column of the departments table', 
	PRIMARY KEY (EMPLOYEE_ID)
   );
  ALTER TABLE EMPLOYEES COMMENT = 'employees table. Contains 107 rows. References with departments, jobs, job_history tables. Contains a self reference.';


  CREATE TABLE JOB_HISTORY 
   (	JOB_HISTORY_ID INT PRIMARY KEY AUTO_INCREMENT,
        EMPLOYEE_ID INT COMMENT 'A not null column in the complex primary key employee_id+start_date. Foreign key to employee_id column of the employee table', 
	START_DATE DATE COMMENT 'A not null column in the complex primary key employee_id+start_date. Must be less than the end_date of the job_history table. (enforced by constraint jhist_date_interval)', 
	END_DATE DATE COMMENT 'Last day of the employee in this job role. A not null column. Must be greater than the start_date of the job_history table. (enforced by constraint jhist_date_interval)', 
	JOB_ID VARCHAR(10) COMMENT 'Job role in which the employee worked in the past; foreign key to job_id column in the jobs table. A not null column.', 
	DEPARTMENT_ID INT COMMENT 'Department id in which the employee worked in the past; foreign key to deparment_id column in the departments table'
   );
  ALTER TABLE JOB_HISTORY COMMENT = 'Table that stores job history of the employees. If an employee changes departments within the job or changes jobs within the department, new rows get inserted into this table with old job information of the employee. Contains a complex primary key: employee_id+start_date. Contains 25 rows. References with jobs, employees, and departments tables.';


  CREATE TABLE JOBS 
   (	JOB_ID VARCHAR(10) COMMENT 'Primary key of jobs table.', 
	JOB_TITLE VARCHAR(35) COMMENT 'A not null column that shows job title, e.g. AD_VP, FI_ACCOUNTANT', 
	MIN_SALARY INT COMMENT 'Minimum salary for a job title.', 
	MAX_SALARY INT COMMENT 'Maximum salary for a job title', 
	PRIMARY KEY (JOB_ID)
   );
  ALTER TABLE JOBS COMMENT = 'jobs table with job titles and salary ranges. Contains 19 rows.
References with employees and job_history table.';


  CREATE TABLE LOCATIONS 
   (	LOCATION_ID INT COMMENT 'Primary key of locations table', 
	STREET_ADDRESS VARCHAR(40) COMMENT 'Street address of an office, warehouse, or production site of a company. Contains building number and street name', 
	POSTAL_CODE VARCHAR(12) COMMENT 'Postal code of the location of an office, warehouse, or production site of a company.', 
	CITY VARCHAR(30) COMMENT 'A not null column that shows city where an office, warehouse, or production site of a company is located.', 
	STATE_PROVINCE VARCHAR(25) COMMENT 'State or Province where an office, warehouse, or production site of a company is located.', 
	COUNTRY_ID CHAR(2) COMMENT 'Country where an office, warehouse, or production site of a company is located. Foreign key to country_id column of the countries table.', 
	PRIMARY KEY (LOCATION_ID)
   );
  ALTER TABLE LOCATIONS COMMENT = 'Locations table that contains specific address of a specific office, warehouse, and/or production site of a company. Does not store addresses / locations of customers. Contains 23 rows; references with the departments and countries tables.';


  CREATE TABLE REGIONS 
   (	REGION_ID INT COMMENT '', 
	REGION_NAME VARCHAR(25) COMMENT '', 
	PRIMARY KEY (REGION_ID)
   );
  ALTER TABLE REGIONS COMMENT = '';



















########################################################
##  Ref Constraints for Table COUNTRIES
########################################################

  ALTER TABLE COUNTRIES ADD CONSTRAINT COUNTR_REG_FK FOREIGN KEY (REGION_ID)
	  REFERENCES REGIONS (REGION_ID) ;
########################################################
##  Ref Constraints for Table DEPARTMENTS
########################################################

  ALTER TABLE DEPARTMENTS ADD CONSTRAINT DEPT_LOC_FK FOREIGN KEY (LOCATION_ID)
	  REFERENCES LOCATIONS (LOCATION_ID) ;
########################################################
##  Ref Constraints for Table EMPLOYEES
########################################################

  ALTER TABLE EMPLOYEES ADD CONSTRAINT EMP_DEPT_FK FOREIGN KEY (DEPARTMENT_ID)
	  REFERENCES DEPARTMENTS (DEPARTMENT_ID) ;
  ALTER TABLE EMPLOYEES ADD CONSTRAINT EMP_JOB_FK FOREIGN KEY (JOB_ID)
	  REFERENCES JOBS (JOB_ID) ;
  ALTER TABLE EMPLOYEES ADD CONSTRAINT EMP_MANAGER_FK FOREIGN KEY (MANAGER_ID)
	  REFERENCES EMPLOYEES (EMPLOYEE_ID) ;
########################################################
##  Ref Constraints for Table JOB_HISTORY
########################################################

  ALTER TABLE JOB_HISTORY ADD CONSTRAINT JHIST_DEPT_FK FOREIGN KEY (DEPARTMENT_ID)
	  REFERENCES DEPARTMENTS (DEPARTMENT_ID) ;
  ALTER TABLE JOB_HISTORY ADD CONSTRAINT JHIST_EMP_FK FOREIGN KEY (EMPLOYEE_ID)
	  REFERENCES EMPLOYEES (EMPLOYEE_ID) ;
  ALTER TABLE JOB_HISTORY ADD CONSTRAINT JHIST_JOB_FK FOREIGN KEY (JOB_ID)
	  REFERENCES JOBS (JOB_ID) ;
########################################################
##  Ref Constraints for Table LOCATIONS
########################################################

  ALTER TABLE LOCATIONS ADD CONSTRAINT LOC_C_ID_FK FOREIGN KEY (COUNTRY_ID)
	  REFERENCES COUNTRIES (COUNTRY_ID) ;
